for name,fn in [('h',lambda i,j:(i,23-j)),('v',lambda i,j:(23-i,j)),('d',lambda i,j:(j,i)),('ad',lambda i,j:(23-j,23-i))]:
 bad=[(i,j,g[i][j],g[fn(i,j)[0]][fn(i,j)[1]]) for i in range(24) for j in range(24) if g[i][j]!=2 and g[fn(i,j)[0]][fn(i,j)[1]]!=2 and g[i][j]!=g[fn(i,j)[0]][fn(i,j)[1]]]
 print(name,len(bad),bad[:2])

def orbit(r,c): return {(r,c),(c,r),(23-r,c),(r,23-c),(23-c,23-r),(c,23-r),(23-r,23-c),(23-c,r)}
issues=[]; out=[row[:] for row in g]
for r in range(24):
 for c in range(24):
  if g[r][c]==2:
   vals=[g[i][j] for i,j in orbit(r,c) if g[i][j]!=2]
   if not vals: issues.append((r,c,vals))
   elif len(set(vals))>1: issues.append((r,c,vals))
   else: out[r][c]=vals[0]
len(issues),issues[:5],sum(x==2 for row in out for x in row)
